mapper.select:
SELECT flrc_date flrcDate, IFNULL(w.cstm_name,q.flrc_airl_name) flrcAirlName, e.apcd_iata_code apcdIataCode, flrc_flight_no flrcFlightNo, flrc_aircrft_no flrcAircrftNo, flrc_aircrft_type flrcAircrftType, flrc_stat_time flrcStatTime, flrc_fuel_vol flrcFuelVol, flrc_quantity flrcQuantity, IFNULL(q.flrc_bwtar,'未知') flrcBwtar, flrc_no flrcNo, f.flgt_trsnm4 AS flightValic, f.flgt_trsnm5 AS flgtVialc, q.arcr_custom_num arcrCustomNum FROM T_FUEL_RECPT q LEFT JOIN T_CUSTOM w ON w.cstm_num = q.arcr_custom_num left join T_AIRPORT_CODE e on q.flrc_airport_code=e.apcd_cnaf_airport_code LEFT JOIN T_FLIGHT f ON q.flgt_id = f.flgt_id WHERE 1 = 1
and q.flrc_date >= #{ startTime }
and q.flrc_date <= #{ endTime }
AND q.flrc_airport_code = #{ staffAirportCode }
order by q.flrc_date desc,w.cstm_name

SELECT tfr.flrc_date flrcDate,cast(tfr.arcr_custom_num as UNSIGNED INTEGER) arcrCustomNum,IFNULL( tac.cstm_name,tfr.arcr_custom_num ) AS flrcAirlName, tfr.flrcNo, tfr.flrcFuelVol, tfr.flrcQuantity, IFNULL(flrc_bwtar,'未知') flrcBwtar, flrc_type flrcType FROM ( SELECT flrc_date, arcr_custom_num AS flrcAirlCode, count( 1 ) AS flrcNo, sum( flrc_fuel_vol ) AS flrcFuelVol, sum( flrc_quantity ) AS flrcQuantity, arcr_custom_num,flrc_bwtar,flrc_type FROM T_FUEL_RECPT WHERE 1 = 1 AND flrc_bwtar = "B" AND flrc_type = 2
and flrc_date >= #{ startTime }
and flrc_date <= #{ endTime }
AND flrc_airport_code = #{ staffAirportCode }
AND arcr_custom_num!= "" and arcr_custom_num is not null GROUP BY arcr_custom_num,flrc_date,flrc_bwtar,flrc_type ) tfr LEFT JOIN T_CUSTOM tac ON LPAD(tac.cstm_num,10,"0") = LPAD(tfr.flrcAirlCode,10,"0") order by tfr.flrc_date desc,flrcAirlName,flrc_type

SELECT tfr.flrc_date flrcDate,cast(tfr.arcr_custom_num as UNSIGNED INTEGER) arcrCustomNum,IFNULL( tac.cstm_name,tfr.arcr_custom_num ) AS flrcAirlName, tfr.flrcNo, tfr.flrcFuelVol, tfr.flrcQuantity, IFNULL(flrc_bwtar,'未知') flrcBwtar FROM ( SELECT flrc_date, arcr_custom_num AS flrcAirlCode, count( 1 ) AS flrcNo, sum( flrc_fuel_vol ) AS flrcFuelVol, sum( flrc_quantity ) AS flrcQuantity, arcr_custom_num,flrc_bwtar FROM T_FUEL_RECPT WHERE 1 = 1
and flrc_date >= #{ startTime }
and flrc_date <= #{ endTime }
AND flrc_airport_code = #{ staffAirportCode }
GROUP BY arcr_custom_num,flrc_date,flrc_bwtar ) tfr LEFT JOIN T_CUSTOM tac ON tac.cstm_num = tfr.flrcAirlCode order by tfr.flrc_date desc,flrcAirlName

SELECT tfr.flrc_date flrcDate,cast(tfr.arcr_custom_num as UNSIGNED INTEGER) arcrCustomNum,IFNULL( tac.cstm_name,tfr.arcr_custom_num ) AS flrcAirlName, tfr.flrcNo, tfr.flrcFuelVol, tfr.flrcQuantity FROM ( SELECT flrc_date, arcr_custom_num AS flrcAirlCode, count( 1 ) AS flrcNo, sum( flrc_fuel_vol ) AS flrcFuelVol, sum( flrc_quantity ) AS flrcQuantity, arcr_custom_num FROM T_FUEL_RECPT WHERE 1 = 1
and flrc_date >= #{ startTime }
and flrc_date <= #{ endTime }
AND flrc_airport_code = #{ staffAirportCode }
GROUP BY arcr_custom_num,flrc_date ) tfr LEFT JOIN T_CUSTOM tac ON tac.cstm_num = tfr.flrcAirlCode order by tfr.flrc_date desc,flrcAirlName

SELECT tfr3.flrcDate, tfr3.flrcVehiNum,
tfr3.flrcNo, tfr3.flrcFuelVol, tfr3.flrcQuantity, round( tfr3.flrcQuantity / tfr3.flrcNo, 3 ) AS flrcVehiNum, round( tfr3.flrcQuantity / tfr3.flrcNo, 3 ) AS flrcFiguars, round(tfr3.flrcMeterStat,3) as flrcMeterStat, round(tfr3.flrcQuantity / tfr3.flrcMeterStat,3) as flrcMeterFnsh FROM ( SELECT (sum(a.poor)/3600) AS flrcMeterStat, a.flrc_date AS flrcDate,
a.flrc_vehi_num AS flrcVehiNum, count(1) AS flrcNo, round(sum(a.flrc_fuel_vol), 3) AS flrcFuelVol, round(sum(a.flrc_quantity), 3) AS flrcQuantity FROM (select * ,TIMESTAMPDIFF(SECOND,flrc_stat_time,flrc_fnsh_time) AS poor from T_FUEL_RECPT) a WHERE 1 = 1
and flrc_date >= #{ startTime }
and flrc_date <= #{ endTime }
AND flrc_airport_code = #{ staffAirportCode }
GROUP BY a.flrc_date, a.flrc_vehi_num ) tfr3

SELECT tfr.flrcDate, tfr.flrcDeliverId AS flrcDeliverId, ts.staff_name AS flrcDeliverName, tfr.flrcNo, tfr.flrcFuelVol, tfr.flrcQuantity, round( tfr.flrcQuantity / tfr.flrcNo, 3 ) AS flrcFiguars, round(tfr.flrcMeterStat,3) as flrcMeterStat, round(tfr.flrcQuantity / tfr.flrcMeterStat,3) as flrcMeterFnsh FROM ( SELECT a.flrc_date AS flrcDate, a.flrc_deliver_id AS flrcDeliverId, count(1) AS flrcNo, round(sum(a.flrc_fuel_vol), 3) AS flrcFuelVol, round(sum(a.flrc_quantity), 3) AS flrcQuantity, (sum(a.poor)/3600) AS flrcMeterStat FROM (select *,(TIMESTAMPDIFF(SECOND,flrc_stat_time,flrc_fnsh_time)) AS poor from T_FUEL_RECPT) a WHERE 1 = 1
and flrc_date >= #{ startTime }
and flrc_date <= #{ endTime }
AND flrc_airport_code = #{ staffAirportCode }
GROUP BY a.flrc_date, a.flrc_deliver_id
) tfr LEFT JOIN T_STAFF ts ON ts.staff_id = tfr.flrcDeliverId

SELECT tfr.flrc_date flrcDate, cast( tfr.arcr_custom_num AS UNSIGNED INTEGER ) arcrCustomNum, IFNULL( tac.cstm_name, tfr.arcr_custom_num ) AS flrcAirlName, tfr.flrcNo, tfr.flrc_type flrcType, tfr.dayFuelVol, tfr.dayFuelQuantity, IFNULL( flrc_bwtar, '未知' ) flrcBwtar FROM ( SELECT flrc_date, flrc_type, count( 1 ) AS flrcNo, sum( flrc_fuel_vol ) AS dayFuelVol, sum( flrc_quantity ) AS dayFuelQuantity, arcr_custom_num, flrc_bwtar FROM T_FUEL_RECPT WHERE 1 = 1
and flrc_date >= #{ startTime }
and flrc_date <= #{ endTime }
AND flrc_airport_code = #{ staffAirportCode }
GROUP BY arcr_custom_num, flrc_date, flrc_type, flrc_bwtar
) tfr LEFT JOIN T_CUSTOM tac ON tac.cstm_num = tfr.arcr_custom_num order by tfr.flrc_date desc,flrcAirlName
